text:
Implemented a Codex trace converter with support for:

- ATIF `trajectory.json` files
- Codex session JSON files containing `events`
- Recursive directory ingestion
- JSON and JSONL inputs
- Successful examples by default
- Optional failed-example inclusion
- Tool-call and tool-output conversion
- Bounded tool output
- Prompt/completion token statistics
- JSONL output suitable for Yeto training ingestion

### `yeto/codex_traces.py`

```python
from __future__ import annotations

import argparse
import json
import re
import sys
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Iterable, Iterator


DEFAULT_MAX_TOOL_OUTPUT_CHARS = 4_000


@dataclass
class ConversionOptions:
    include_failures: bool = False
    max_tool_output_chars: int = DEFAULT_MAX_TOOL_OUTPUT_CHARS


def _truncate(value: Any, limit: int) -> str:
    if value is None:
        return ""

    if not isinstance(value, str):
        value = json.dumps(value, ensure_ascii=False, sort_keys=True)

    if len(value) <= limit:
        return value

    omitted = len(value) - limit
    return f"{value[:limit]}\n...[truncated {omitted} chars]"


def _text(value: Any) -> str:
    if value is None:
        return ""

    if isinstance(value, str):
        return value

    if isinstance(value, list):
        return "\n".join(_text(item) for item in value)

    if isinstance(value, dict):
        for key in ("content", "text", "message", "value"):
            if key in value:
                return _text(value[key])

    return json.dumps(value, ensure_ascii=False, sort_keys=True)


def _estimate_tokens(text: str) -> int:
    """
    Lightweight fallback tokenizer.

    If Yeto already provides a tokenizer, this function can be replaced by the
    project tokenizer without changing the converter interface.
    """
    if not text:
        return 0

    return len(re.findall(r"\w+|[^\w\s]", text, flags=re.UNICODE))


def _message_token_count(message: dict[str, Any]) -> int:
    parts: list[str] = []

    content = message.get("content")
    if content:
        parts.append(_text(content))

    for tool_call in message.get("tool_calls", []):
        parts.append(json.dumps(tool_call, ensure_ascii=False))

    return _estimate_tokens("\n".join(parts))


def _stats(messages: list[dict[str, Any]]) -> dict[str, int]:
    prompt_tokens = 0
    completion_tokens = 0

    for message in messages:
        count = _message_token_count(message)
        if message.get("role") == "assistant":
            completion_tokens += count
        else:
            prompt_tokens += count

    return {
        "prompt_tokens": prompt_tokens,
        "completion_tokens": completion_tokens,
        "total_tokens": prompt_tokens + completion_tokens,
    }


def _tool_call(
    tool_name: str,
    arguments: Any,
    index: int,
    call_id: str | None = None,
) -> dict[str, Any]:
    if isinstance(arguments, str):
        argument_text = arguments
    else:
        argument_text = json.dumps(arguments or {}, ensure_ascii=False)

    return {
        "id": call_id or f"tool_call_{index}",
        "type": "function",
        "function": {
            "name": tool_name,
            "arguments": argument_text,
        },
    }


def _success_value(record: dict[str, Any]) -> bool | None:
    extra = record.get("extra")
    if isinstance(extra, dict) and "success" in extra:
        return bool(extra["success"])

    metadata = record.get("metadata")
    if isinstance(metadata, dict):
        if "success" in metadata:
            return bool(metadata["success"])

        status = metadata.get("status")
        if status in {"success", "succeeded", "completed", "complete"}:
            return True
        if status in {"failure", "failed", "error"}:
            return False

    status = record.get("status")
    if status in {"success", "succeeded", "completed", "complete"}:
        return True
    if status in {"failure", "failed", "error"}:
        return False

    return None


def _trajectory_metadata(
    record: dict[str, Any],
    source_file: Path,
    source_format: str,
) -> dict[str, Any]:
    extra = record.get("extra")
    metadata = record.get("metadata")

    result: dict[str, Any] = {
        "source": "codex",
        "source_format": source_format,
        "source_file": str(source_file),
    }

    if isinstance(extra, dict):
        for key in ("trajectory_id", "task_id", "reward", "success"):
            if key in extra:
                result[key] = extra[key]

    if isinstance(metadata, dict):
        for key in ("trajectory_id", "task_id", "session_id", "reward", "success"):
            if key in metadata:
                result[key] = metadata[key]

    for key in ("trajectory_id", "task_id", "session_id", "reward"):
        if key in record:
            result[key] = record[key]

    success = _success_value(record)
    if success is not None:
        result["success"] = success

    return result


def _convert_atif(
    record: dict[str, Any],
    source_file: Path,
    options: ConversionOptions,
) -> dict[str, Any] | None:
    success = _success_value(record)
    if success is False and not options.include_failures:
        return None

    messages: list[dict[str, Any]] = []
    steps = record.get("steps", [])

    if not isinstance(steps, list):
        return None

    tool_index = 0

    for step in steps:
        if not isinstance(step, dict):
            continue

        source = step.get("source") or step.get("role")
        source = str(source).lower() if source is not None else ""

        if source in {"system", "user"}:
            content = _text(step.get("message", step.get("content")))
            if content:
                messages.append({
                    "role": source,
                    "content": content,
                })

        elif source in {"agent", "assistant", "model"}:
            content = _text(step.get("message", step.get("content")))
            message: dict[str, Any] = {
                "role": "assistant",
                "content": content,
            }

            tool_calls = (
                step.get("tool_calls")
                or step.get("tool_calls_made")
                or step.get("actions")
                or []
            )

            converted_calls: list[dict[str, Any]] = []
            if isinstance(tool_calls, list):
                for call in tool_calls:
                    if not isinstance(call, dict):
                        continue

                    name = (
                        call.get("name")
                        or call.get("tool_name")
                        or call.get("function", {}).get("name")
                    )
                    if not name:
                        continue

                    arguments = (
                        call.get("arguments")
                        if "arguments" in call
                        else call.get("input", call.get("function", {}).get("arguments", {}))
                    )

                    converted_calls.append(
                        _tool_call(
                            str(name),
                            arguments,
                            tool_index,
                            call.get("id") or call.get("tool_call_id"),
                        )
                    )
                    tool_index += 1

            if converted_calls:
                message["tool_calls"] = converted_calls

            if message["content"] or converted_calls:
                messages.append(message)

        elif source in {"tool", "observation", "environment"}:
            content = (
                step.get("output")
                if "output" in step
                else step.get("observation", step.get("result", step.get("message")))
            )

            content = _truncate(content, options.max_tool_output_chars)
            if not content:
                continue

            tool_message: dict[str, Any] = {
                "role": "tool",
                "content": content,
            }

            tool_name = step.get("tool_name") or step.get("name")
            if tool_name:
                tool_message["name"] = str(tool_name)

            tool_call_id = step.get("tool_call_id") or step.get("call_id")
            if tool_call_id:
                tool_message["tool_call_id"] = str(tool_call_id)

            messages.append(tool_message)

    if not messages:
        return None

    metadata = _trajectory_metadata(record, source_file, "atif")
    return {
        "messages": messages,
        "metadata": metadata,
        "stats": _stats(messages),
    }


def _event_role(event_type: str) -> str | None:
    event_type = event_type.lower()

    if event_type in {"user_message", "user", "prompt"}:
        return "user"

    if event_type in {"assistant_message", "assistant", "response", "model_message"}:
        return "assistant"

    if event_type in {
        "tool_invocation",
        "tool_result",
        "tool_output",
        "observation",
    }:
        return "tool"

    return None


def _convert_session(
    record: dict[str, Any],
    source_file: Path,
    options: ConversionOptions,
) -> dict[str, Any] | None:
    success = _success_value(record)
    if success is False and not options.include_failures:
        return None

    events = record.get("events")
    if not isinstance(events, list):
        return None

    messages: list[dict[str, Any]] = []

    for event in events:
        if not isinstance(event, dict):
            continue

        event_type = (
            event.get("type")
            or event.get("event_type")
            or event.get("kind")
            or ""
        )
        role = _event_role(str(event_type))
        if role is None:
            continue

        if role == "tool":
            content = (
                event.get("output")
                if "output" in event
                else event.get("result", event.get("content", event.get("message")))
            )
            content = _truncate(content, options.max_tool_output_chars)

            if not content:
                continue

            message: dict[str, Any] = {
                "role": "tool",
                "content": content,
            }

            tool_name = event.get("tool_name") or event.get("name")
            if tool_name:
                message["name"] = str(tool_name)

            call_id = event.get("tool_call_id") or event.get("call_id")
            if call_id:
                message["tool_call_id"] = str(call_id)

            messages.append(message)
            continue

        content = _text(
            event.get("content", event.get("message", event.get("text")))
        )

        if content:
            messages.append({
                "role": role,
                "content": content,
            })

    if not messages:
        return None

    metadata = _trajectory_metadata(record, source_file, "codex_session")
    return {
        "messages": messages,
        "metadata": metadata,
        "stats": _stats(messages),
    }


def _detect_format(record: dict[str, Any]) -> str | None:
    if isinstance(record.get("steps"), list):
        return "atif"

    if isinstance(record.get("events"), list):
        return "codex_session"

    return None


def _load_json_file(path: Path) -> Iterator[dict[str, Any]]:
    if path.suffix.lower() == ".jsonl":
        with path.open("r", encoding="utf-8") as handle:
            for line_number, line in enumerate(handle, start=1):
                line = line.strip()
                if not line:
                    continue

                try:
                    value = json.loads(line)
                except json.JSONDecodeError as exc:
                    raise ValueError(
                        f"{path}:{line_number}: invalid JSONL: {exc}"
                    ) from exc

                if isinstance(value, dict):
                    yield value
        return

    with path.open("r", encoding="utf-8") as handle:
        value = json.load(handle)

    if isinstance(value, dict):
        yield value
    elif isinstance(value, list):
        for item in value:
            if isinstance(item, dict):
                yield item


def _input_files(inputs: Iterable[str]) -> Iterator[Path]:
    seen: set[Path] = set()

    for raw_input in inputs:
        path = Path(raw_input)

        if path.is_file():
            candidates = [path]
        elif path.is_dir():
            candidates = sorted(
                candidate
                for candidate in path.rglob("*")
                if candidate.is_file()
                and candidate.suffix.lower() in {".json", ".jsonl"}
            )
        else:
            raise FileNotFoundError(path)

        for candidate in candidates:
            candidate = candidate.resolve()
            if candidate not in seen:
                seen.add(candidate)
                yield candidate


def convert_paths(
    inputs: Iterable[str],
    options: ConversionOptions | None = None,
) -> Iterator[dict[str, Any]]:
    options = options or ConversionOptions()

    for source_file in _input_files(inputs):
        for record in _load_json_file(source_file):
            source_format = _detect_format(record)

            if source_format == "atif":
                converted = _convert_atif(record, source_file, options)
            elif source_format == "codex_session":
                converted = _convert_session(record, source_file, options)
            else:
                continue

            if converted is not None:
                yield converted


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Convert Codex ATIF trajectories and session logs into Yeto JSONL."
    )
    parser.add_argument(
        "inputs",
        nargs="+",
        help="Input files or directories. Directories are searched recursively.",
    )
    parser.add_argument(
        "-o",
        "--output",
        required=True,
        help="Output JSONL file, or '-' for stdout.",
    )
    parser.add_argument(
        "--include-failures",
        action="store_true",
        help="Include trajectories marked as unsuccessful.",
    )
    parser.add_argument(
        "--max-tool-output-chars",
        type=int,
        default=DEFAULT_MAX_TOOL_OUTPUT_CHARS,
        help=f"Maximum tool-output length. Default: {DEFAULT_MAX_TOOL_OUTPUT_CHARS}.",
    )
    return parser


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)

    if args.max_tool_output_chars < 0:
        parser.error("--max-tool-output-chars must be non-negative")

    options = ConversionOptions(
        include_failures=args.include_failures,
        max_tool_output_chars=args.max_tool_output_chars,
    )

    output_handle = sys.stdout
    should_close = False

    if args.output != "-":
        output_handle = open(args.output, "w", encoding="utf-8")
        should_close = True

    converted = 0

    try:
        for example in convert_paths(args.inputs, options):
            output_handle.write(
                json.dumps(example, ensure_ascii=False, separators=(",", ":"))
                + "\n"
            )
            converted += 1
    finally:
        if should_close:
            output_handle.close()

    if args.output != "-":
        print(f"Wrote {converted} examples to {args.output}", file=sys.stderr)

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
```

### CLI entry point

Add this to the project’s `pyproject.toml`:

```toml
[project.scripts]
yeto-codex-traces = "yeto.codex_traces:main"
```

Example usage:

```bash
yeto-codex-traces \
  ./codex_runs \
  --output ./data/codex-traces.jsonl
```

Include failed trajectories:

```bash
yeto-codex-traces \
  ./codex_runs \
  --include-failures \
  --max-tool-output-chars 8000 \
  --output ./data/codex-traces-all.jsonl
```

