  LayoutChangeEvent,
} from 'react-native';

type Props = {
  value: number;
  onChange: (value: number) => void;
  min?: number;
  max?: number;
  step?: number;
};

const TICK_WIDTH = 16;
const TRACK_PADDING = 18;
const VISIBLE_TICKS = 17;
const LABEL_EVERY = 5;

export default function LengthSlider({
  value,
  onChange,
  min = 5,
  max = 120,
  step = 5,
}: Props) {
  const trackWidth = useRef(0);
  const animatedRailX = useRef(new Animated.Value(0)).current;
  const startValue = useRef(value);

  const values = useMemo(() => {
    const count = Math.floor((max - min) / step) + 1;
    return Array.from({ length: count }, (_, i) => min + i * step);
  }, [min, max, step]);

  const clamp = (n: number) => Math.max(min, Math.min(max, n));

  const valueToX = (v: number) => {
    const index = (v - min) / step;
    return index * TICK_WIDTH;
  };

  const xToValue = (x: number) => {
    const index = Math.round(x / TICK_WIDTH);
    return clamp(min + index * step);
  };

  useEffect(() => {
    const x = valueToX(value);
    Animated.timing(animatedRailX, {
      toValue: -x + trackWidth.current / 2 - TICK_WIDTH / 2,
      duration: 180,
      useNativeDriver: true,
    }).start();
  }, [value, animatedRailX]);

  const onTrackLayout = (e: LayoutChangeEvent) => {
    trackWidth.current = e.nativeEvent.layout.width;
  };

  const panResponder = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => true,
        onMoveShouldSetPanResponder: (_, g) => Math.abs(g.dx) > 2,
        onPanResponderGrant: () => {
          startValue.current = value;
        },
        onPanResponderMove: (_, g) => {
          const startX = valueToX(startValue.current);
          const nextX = startX - g.dx;
          onChange(xToValue(nextX));
        },
        onPanResponderRelease: (_, g) => {
          const startX = valueToX(startValue.current);
          const nextX = startX - g.dx;
          onChange(xToValue(nextX));
        },
      }),
    [value, min, max, step]
  );

  return (
    <View style={styles.container}>
      <View style={styles.track} onLayout={onTrackLayout}>
        <Animated.View
          style={[
            styles.rail,
            {
              transform: [{ translateX: animatedRailX }],
            },
          ]}
          {...panResponder.panHandlers}
        >
          {values.map((v) => {
            const isLabel = ((v - min) / step) % LABEL_EVERY === 0;
            const isOutOfRange =
              v < value - (VISIBLE_TICKS * step) / 2 ||
              v > value + (VISIBLE_TICKS * step) / 2;

            return (
              <View key={v} style={styles.tickColumn}>
                <View
                  style={[
                    styles.tick,
                    isLabel && styles.longTick,
                    isOutOfRange && styles.fadedTick,
                  ]}
                />
                {isLabel && <Text style={styles.label}>{v}s</Text>}
              </View>
            );
          })}
        </Animated.View>
        <Pressable
          style={StyleSheet.absoluteFill}
          onPress={(e) => {
            const x = e.nativeEvent.locationX - trackWidth.current / 2;
            onChange(xToValue(valueToX(value) + x));
          }}
        />
        <View pointerEvents="none" style={styles.thumb} />
      </View>
      <Text style={styles.valueLabel}>{value}s</Text>
    </View>
  );
}

