import { useOnboarding } from '../context/OnboardingContext';

const { width } = Dimensions.get('window');

// Type definitions
type Gender = 'male' | 'female' | null;

interface GenderOption {
  value: Gender;
  label: string;
  icon: string;
  color: string;
}

interface WeightData {
  weight: number;
  unit: 'lbs' | 'kg';
}

// Constants
const MIN_WEIGHT_LBS = 50;
const MAX_WEIGHT_LBS = 400;
const TICK_SPACING = 18; // pixels between ticks
const RULER_HEIGHT = 180;
const MAJOR_TICK_HEIGHT = 40;
const MINOR_TICK_HEIGHT = 24;

export default function PersonalDetailsScreen() {
  const router = useRouter();
  const { onboardingData, updateOnboardingData } = useOnboarding();

  // State
  const [gender, setGender] = useState<Gender>(onboardingData.gender || null);
  const [weight, setWeight] = useState<WeightData>({
    weight: onboardingData.weight || 154,
    unit: onboardingData.weightUnit || 'lbs',
  });
  const [isDragging, setIsDragging] = useState(false);

  // Animation
  const rulerTranslateX = useRef(new Animated.Value(0)).current;
  const lastWeightRef = useRef(weight.weight);

  // Gender options
  const genderOptions: GenderOption[] = [
    {
      value: 'male',
      label: 'Male',
      icon: 'male',
      color: '#4A90E2',
    },
    {
      value: 'female',
      label: 'Female',
      icon: 'female',
      color: '#E91E63',
    },
  ];

  // Convert weight between units
  const convertWeight = (value: number, fromUnit: 'lbs' | 'kg', toUnit: 'lbs' | 'kg'): number => {
    if (fromUnit === toUnit) return value;
    if (fromUnit === 'lbs' && toUnit === 'kg') {
      return Math.round(value * 0.453592 * 10) / 10;
    }
    return Math.round(value * 2.20462 * 10) / 10;
  };

  // Handle unit toggle
  const handleUnitToggle = () => {
    const newUnit = weight.unit === 'lbs' ? 'kg' : 'lbs';
    const convertedWeight = convertWeight(weight.weight, weight.unit, newUnit);
    setWeight({
      weight: convertedWeight,
      unit: newUnit,
    });
  };

  // Get weight range based on unit
  const getWeightRange = () => {
    if (weight.unit === 'lbs') {
      return { min: MIN_WEIGHT_LBS, max: MAX_WEIGHT_LBS };
    }
    return {
      min: Math.round(MIN_WEIGHT_LBS * 0.453592),
      max: Math.round(MAX_WEIGHT_LBS * 0.453592),
    };
  };

  // Calculate ruler position based on weight
  const getRulerPosition = (weightValue: number) => {
    const { min } = getWeightRange();
    return (weightValue - min) * TICK_SPACING * 2; // 2 ticks per unit
  };

  // Pan responder for ruler interaction
  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onMoveShouldSetPanResponder: (_, gestureState) => {
        return Math.abs(gestureState.dx) > Math.abs(gestureState.dy);
      },
      onPanResponderGrant: () => {
        setIsDragging(true);
        rulerTranslateX.setOffset(-(getRulerPosition(weight.weight)));
        rulerTranslateX.setValue(0);
      },
      onPanResponderMove: (_, gestureState) => {
        const { min, max } = getWeightRange();
        const newPosition = -(getRulerPosition(weight.weight)) + gestureState.dx;
        const newWeight = min + Math.round(Math.abs(newPosition) / (TICK_SPACING * 2));
        const clampedWeight = Math.max(min, Math.min(max, newWeight));

        if (clampedWeight !== weight.weight) {
          setWeight(prev => ({
            ...prev,
            weight: clampedWeight,
          }));
        }

        rulerTranslateX.setValue(gestureState.dx);
      },
      onPanResponderRelease: () => {
        setIsDragging(false);
        rulerTranslateX.flattenOffset();

        // Snap to nearest tick
        const { min } = getWeightRange();
        const currentPosition = getRulerPosition(weight.weight);
        Animated.spring(rulerTranslateX, {
          toValue: -currentPosition,
          useNativeDriver: true,
          tension: 100,
          friction: 10,
        }).start();
      },
    })
  ).current;

  // Update ruler position when weight changes externally
  useEffect(() => {
    if (!isDragging && weight.weight !== lastWeightRef.current) {
      const position = -getRulerPosition(weight.weight);
      Animated.spring(rulerTranslateX, {
        toValue: position,
        useNativeDriver: true,
        tension: 100,
        friction: 10,
      }).start();
    }
    lastWeightRef.current = weight.weight;
  }, [weight.weight, weight.unit, isDragging]);

  // Generate ruler ticks
  const generateTicks = () => {
    const { min, max } = getWeightRange();
    const ticks = [];
    const totalTicks = (max - min) * 2 + 1; // 0.5 increments

    for (let i = 0; i < totalTicks; i++) {
