      const isMedium = value % 1 === 0;

      ticks.push(
        <View
          key={i}
          style={[
            styles.tickContainer,
            { width: TICK_SPACING },
          ]}
        >
          <View
            style={[
              styles.tick,
              isMajor
                ? styles.majorTick
                : isMedium
                ? styles.mediumTick
                : styles.minorTick,
            ]}
          />
          {isMajor && (
            <Text style={styles.tickLabel}>
              {Math.round(value)}
            </Text>
          )}
        </View>
      );
    }
    return ticks;
  };

  // Handle continue
  const handleContinue = () => {
