  const displayWeight = weight.unit === 'lbs'
    ? Math.round(weight.weight)
    : Math.round(weight.weight * 10) / 10;

  return (
    <SafeAreaView style={styles.container}>
      {/* Header */}
      <View style={styles.header}>
        <TouchableOpacity
          style={styles.backButton}
          onPress={handleBack}
          activeOpacity={0.7}
        >
          <Ionicons name="arrow-back" size={24} color="#333" />
        </TouchableOpacity>
        <View style={styles.progressContainer}>
          <View style={styles.progressBar}>
            <View style={[styles.progressFill, { width: '37.5%' }]} />
          </View>
          <Text style={styles.stepText}>3 of 8</Text>
        </View>
        <View style={styles.headerSpacer} />
      </View>

      <ScrollView
        style={styles.scrollView}
        contentContainerStyle={styles.content}
        showsVerticalScrollIndicator={false}
        bounces={false}
      >
        {/* Title Section */}
        <View style={styles.titleSection}>
          <Text style={styles.title}>Tell us about yourself</Text>
          <Text style={styles.subtitle}>
            This helps us personalize your calorie goals
          </Text>
        </View>

        {/* Gender Section */}
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>What's your gender?</Text>
          <View style={styles.genderContainer}>
            {genderOptions.map((option) => (
              <TouchableOpacity
                key={option.value}
                style={[
                  styles.genderCard,
                  gender === option.value && styles.genderCardSelected,
                  gender === option.value && { borderColor: option.color },
                ]}
                onPress={() => setGender(option.value)}
                activeOpacity={0.8}
              >
                <View
                  style={[
                    styles.genderIconContainer,
                    { backgroundColor: `${option.color}15` },
                    gender === option.value && { backgroundColor: `${option.color}25` },
                  ]}
                >
                  <Ionicons
                    name={option.icon as any}
                    size={36}
                    color={option.color}
                  />
                </View>
                <Text
                  style={[
                    styles.genderLabel,
                    gender === option.value && { color: option.color },
                  ]}
                >
                  {option.label}
                </Text>
                {gender === option.value && (
                  <View
                    style={[
                      styles.checkmark,
                      { backgroundColor: option.color },
                    ]}
                  >
                    <Ionicons name="checkmark" size={16} color="#fff" />
                  </View>
                )}
              </TouchableOpacity>
            ))}
          </View>
        </View>

        {/* Weight Section */}
        <View style={styles.section}>
          <View style={styles.weightHeader}>
            <Text style={styles.sectionTitle}>What's your current weight?</Text>
            <TouchableOpacity
              style={styles.unitToggle}
              onPress={handleUnitToggle}
              activeOpacity={0.7}
            >
              <Text
                style={[
                  styles.unitText,
                  weight.unit === 'lbs' && styles.unitTextActive,
                ]}
              >
                lbs
              </Text>
              <View style={styles.unitDivider} />
              <Text
                style={[
                  styles.unitText,
                  weight.unit === 'kg' && styles.unitTextActive,
                ]}
              >
                kg
