                  },
                ]}
              >
                {generateTicks()}
              </Animated.View>
            </View>
          </View>

          <Text style={styles.helperText}>
            Swipe left or right to adjust
          </Text>
        </View>

        {/* Info Card */}
        <View style={styles.infoCard}>
          <Ionicons name="information-circle-outline" size={22} color="#6C63FF" />
          <Text style={styles.infoText}>
