const snapToNearestTick = (offsetX: number) => {
  const index = Math.round(offsetX / tickSpacing);
  const clampedIndex = Math.max(0, Math.min(index, maxValue / 10));
  const snappedOffset = clampedIndex * tickSpacing;
  const snappedValue = clampedIndex * 10;

  rulerRef.current?.scrollTo({
    x: snappedOffset,
    animated: true,
  });

  onValueChange(snappedValue);
};
