import { getDatabase } from "./database";
import { getCurrentUserId } from "./authRepository";

export type SocialProfile = {
  userId: string;
  handle: string;
  displayName: string;
  avatarUrl: string | null;
  bio: string | null;
  followerCount: number;
  followingCount: number;
  profileVisibility: "public" | "private";
  allowMessages: boolean;
  createdAt: string;
  updatedAt: string;
};

function nowIso() {
  return new Date().toISOString();
}

function rowToSocialProfile(row: any): SocialProfile {
  return {
    userId: row.user_id,
    handle: row.handle,
    displayName: row.display_name,
    avatarUrl: row.avatar_url ?? null,
    bio: row.bio ?? null,
    followerCount: Number(row.follower_count ?? 0),
    followingCount: Number(row.following_count ?? 0),
    profileVisibility: row.profile_visibility === "private" ? "private" : "public",
    allowMessages: Number(row.allow_messages ?? 1) === 1,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export async function ensureSocialProfile(input: {
  userId?: string;
  handle?: string;
  displayName?: string;
  avatarUrl?: string | null;
}) {
  const db = await getDatabase();
  const userId = input.userId ?? (await getCurrentUserId());

  if (!userId) {
    throw new Error("Not authenticated");
  }

  const existing = await db.getFirstAsync<any>(
    `SELECT * FROM social_profiles WHERE user_id = ? LIMIT 1`,
    [userId]
  );

  if (existing) {
    return rowToSocialProfile(existing);
  }

  const timestamp = nowIso();
  const baseHandle =
    input.handle?.trim() ||
    `user_${userId.replace(/-/g, "").slice(0, 10)}`;

  await db.runAsync(
    `
      INSERT INTO social_profiles (
        user_id,
        handle,
        display_name,
        avatar_url,
        bio,
        follower_count,
        following_count,
        profile_visibility,
        allow_messages,
        created_at,
        updated_at
      ) VALUES (?, ?, ?, ?, ?, 0, 0, 'public', 1, ?, ?)
    `,
    [
      userId,
      baseHandle,
      input.displayName?.trim() || baseHandle,
      input.avatarUrl ?? null,
      null,
      timestamp,
      timestamp,
    ]
  );

  const created = await db.getFirstAsync<any>(
    `SELECT * FROM social_profiles WHERE user_id = ? LIMIT 1`,
    [userId]
  );

  return rowToSocialProfile(created);
}

export async function getMySocialProfile() {
  const userId = await getCurrentUserId();

  if (!userId) {
    throw new Error("Not authenticated");
  }

  const db = await getDatabase();
  const row = await db.getFirstAsync<any>(
    `SELECT * FROM social_profiles WHERE user_id = ? LIMIT 1`,
    [userId]
  );

  return row ? rowToSocialProfile(row) : null;
}

export async function searchSocialProfiles(query: string) {
  const db = await getDatabase();
  const normalized = query.trim().toLowerCase();

  if (!normalized) {
    return [];
  }

  const rows = await db.getAllAsync<any>(
    `
      SELECT *
      FROM social_profiles
      WHERE lower(handle) LIKE ?
         OR lower(display_name) LIKE ?
      ORDER BY follower_count DESC, display_name ASC
      LIMIT 20
    `,
    [`%${normalized}%`, `%${normalized}%`]
  );

  return rows.map(rowToSocialProfile);
}

export async function getSocialProfileByHandle(handle: string) {
  const db = await getDatabase();
  const row = await db.getFirstAsync<any>(
    `SELECT * FROM social_profiles WHERE lower(handle) = lower(?) LIMIT 1`,
    [handle.trim()]
  );

  return row ? rowToSocialProfile(row) : null;
}
