                    {message}
                  </Text>
                ))}
              </View>
            ) : null}

            <Pressable onPress={handleSignOut} style={styles.signOutButton}>
              <Text style={styles.signOutButtonText}>Sign out</Text>
            </Pressable>
          </View>
        </ScrollView>
      </KeyboardAvoidingView>

      <Modal
        animationType="slide"
        onRequestClose={() => setShowAvatarPicker(false)}
        transparent
        visible={showAvatarPicker}
      >
        <Pressable
          onPress={() => setShowAvatarPicker(false)}
          style={styles.modalBackdrop}
        >
          <Pressable onPress={() => undefined} style={styles.avatarModal}>
            <View style={styles.modalHandle} />
            <Text style={styles.modalTitle}>Choose a profile picture</Text>
            <Text style={styles.modalSubtitle}>
              Pick an image to represent you across ClipNotes.
            </Text>

            <View style={styles.avatarGrid}>
              {AVATAR_OPTIONS.map((avatar) => {
                const selected = avatar.uri === avatarUrl;

                return (
                  <Pressable
                    key={avatar.id}
                    onPress={() => {
                      setAvatarUrl(avatar.uri);
                      setShowAvatarPicker(false);
                    }}
                    style={[
                      styles.avatarOption,
                      selected && styles.avatarOptionSelected,
                    ]}
                  >
                    <Image
                      source={{ uri: avatar.uri }}
                      style={styles.avatarOptionImage}
                    />
                    <Text style={styles.avatarOptionLabel}>{avatar.label}</Text>
                  </Pressable>
                );
              })}
            </View>

            <Pressable
              onPress={() => {
                setAvatarUrl(null);
                setShowAvatarPicker(false);
              }}
              style={styles.removeAvatarButton}
            >
              <Text style={styles.removeAvatarText}>Use no picture</Text>
            </Pressable>
          </Pressable>
        </Pressable>
      </Modal>

      <Modal
        animationType="fade"
        onRequestClose={() => setShowSuccessModal(false)}
        transparent
        visible={showSuccessModal}
      >
        <View style={styles.modalBackdrop}>
          <View style={styles.successModal}>
            <View style={styles.successIcon}>
              <Ionicons name="checkmark" size={28} color="#FFFFFF" />
            </View>
            <Text style={styles.modalTitle}>Account created</Text>
            <Text style={styles.modalSubtitle}>
              Your ClipNotes account is ready. You can now explore people and
              share your favorite clips.
            </Text>

            {authDiagnostics.length > 0 ? (
              <View style={styles.diagnosticsBox}>
                <Text style={styles.diagnosticsTitle}>Some setup warnings</Text>
                {authDiagnostics.map((message) => (
                  <Text key={message} style={styles.diagnosticsText}>
                    {message}
                  </Text>
                ))}
              </View>
            ) : null}

            <Pressable
              onPress={() => {
                setShowSuccessModal(false);
                router.replace("/(app)/(tabs)/home");
              }}
              style={styles.primaryButton}
            >
              <Text style={styles.primaryButtonText}>Continue to ClipNotes</Text>
            </Pressable>
          </View>
        </View>
      </Modal>
    </SafeAreaView>
  );
}

